-- R01 Short Functional Texts: Batch 2
-- 15 A2, 15 B1, 15 B2 questions. All are draft items for teacher testing.
-- No arithmetic or mathematical reasoning is required.
-- Estimated time is stored per item in seconds.
begin;
insert into public.reading_question_bank
(question_code,category,cefr_level,topic,skill,passage,prompt,options,correct_option,rationale,difficulty,estimated_seconds,status)
values
('A2-016','R01','A2','Technology and Society','Understanding instructions','PHONE REPAIR DESK
Please switch off your phone before handing it to the technician. Remove your case and keep your SIM card with you. We will send you a message when the repair is complete.','What should customers do before giving the phone to the technician?','[{"label":"A","text":"Put the phone in a new case."},{"label":"B","text":"Take the SIM card out and keep it."},{"label":"C","text":"Send a message to the technician."},{"label":"D","text":"Leave the phone switched on."}]'::jsonb,'B','The instructions say to remove the SIM card and keep it with you.','core',45,'draft'),
('A2-017','R01','A2','Education and Learning','Identifying purpose','HOMEWORK CLUB
Need a quiet place to study? Join us in Room 12 every Tuesday after school. A teacher will be available to help with difficult questions. Bring your books and remember to sign in.','Why has this notice been written?','[{"label":"A","text":"To invite students to a study session."},{"label":"B","text":"To explain how to become a teacher."},{"label":"C","text":"To announce a change of classroom."},{"label":"D","text":"To remind students to finish a test."}]'::jsonb,'A','The notice invites students to attend the homework club.','core',45,'draft'),
('A2-018','R01','A2','Transportation and Travel','Identifying specific information','TRAIN STATION NOTICE
The ticket office will close early this Friday for staff training. Tickets can still be bought from the machines near the main entrance. Station staff will be available to help passengers.','Where can passengers buy tickets on Friday?','[{"label":"A","text":"At the café beside the platform."},{"label":"B","text":"From the train driver."},{"label":"C","text":"At the machines near the entrance."},{"label":"D","text":"Only from the station manager."}]'::jsonb,'C','The notice directs passengers to the ticket machines near the main entrance.','core',45,'draft'),
('A2-019','R01','A2','Environment and Pollution','Understanding rules','PARK NOTICE
Please keep dogs on a lead near the playground. Dogs are welcome in the park, but owners must clean up after them. The small garden beside the pond is closed while new plants are growing.','Which rule applies to dog owners?','[{"label":"A","text":"Dogs must stay outside the park."},{"label":"B","text":"Dogs must be kept on a lead near the playground."},{"label":"C","text":"Dogs can enter the new garden."},{"label":"D","text":"Owners should leave their dogs near the pond."}]'::jsonb,'B','The notice specifically requires dogs to be on a lead near the playground.','core',50,'draft'),
('A2-020','R01','A2','Health and Nutrition','Understanding advice','SCHOOL HEALTH ROOM
If you feel unwell during the school day, tell your teacher before coming to the health room. Please do not take medicine from another student. A nurse is available until 3 p.m.','What should a student do if they feel ill?','[{"label":"A","text":"Ask another student for medicine."},{"label":"B","text":"Go home without telling anyone."},{"label":"C","text":"Tell the teacher first."},{"label":"D","text":"Wait until the nurse has gone home."}]'::jsonb,'C','The first instruction is to tell the teacher before visiting the health room.','core',45,'draft'),
('A2-021','R01','A2','Media and Youth','Understanding purpose','PHOTOGRAPHY COMPETITION
Show us your best picture of everyday life in our town. Photos must be your own work and should not include people who have not agreed to be photographed. Send your entry to the school media club.','What is an important rule for entries?','[{"label":"A","text":"The photo must be taken abroad."},{"label":"B","text":"The photo must include a famous person."},{"label":"C","text":"The photo must be edited by the media club."},{"label":"D","text":"People in the photo must have agreed to be included."}]'::jsonb,'D','The notice says people should not appear in photos without agreeing to be photographed.','core',50,'draft'),
('A2-022','R01','A2','Cities and Housing','Identifying specific information','FLAT SHARE
A room is available in a shared flat near the university. The room is furnished, and the kitchen is shared with two other people. No smoking is allowed anywhere inside the building. Contact May to arrange a visit.','What is true about the flat?','[{"label":"A","text":"The room has no furniture."},{"label":"B","text":"The kitchen is shared."},{"label":"C","text":"Smoking is allowed in bedrooms."},{"label":"D","text":"The flat is inside the university."}]'::jsonb,'B','The notice states that the kitchen is shared with two other people.','core',45,'draft'),
('A2-023','R01','A2','Food Production','Understanding instructions','COMMUNITY GARDEN
Visitors may pick ripe tomatoes from the marked rows. Please leave the green tomatoes on the plants. Watering cans are beside the garden shed. Return them after use.','Which tomatoes may visitors take?','[{"label":"A","text":"The ripe ones in the marked rows."},{"label":"B","text":"All the tomatoes near the shed."},{"label":"C","text":"The green ones on the plants."},{"label":"D","text":"Only tomatoes that have fallen."}]'::jsonb,'A','Visitors are told to pick ripe tomatoes from the marked rows.','core',45,'draft'),
('A2-024','R01','A2','Sports and Health','Understanding advice','BADMINTON CLUB
New members are welcome. You do not need to bring a racket because the club has some to borrow. Please wear sports shoes with clean soles. Trainers used outside are not suitable for the sports hall.','What should new members bring?','[{"label":"A","text":"Their own badminton racket."},{"label":"B","text":"A pair of clean sports shoes."},{"label":"C","text":"A bottle of sports drink for everyone."},{"label":"D","text":"A permission letter from the coach."}]'::jsonb,'B','The club provides rackets, but members need suitable clean sports shoes.','core',45,'draft'),
('A2-025','R01','A2','Space Exploration','Identifying purpose','SCIENCE MUSEUM
The space exhibition is temporarily closed on Monday morning while new displays are installed. It will reopen at 1 p.m. The rest of the museum will be open as usual.','Why is the space exhibition closed on Monday morning?','[{"label":"A","text":"The museum is having a staff holiday."},{"label":"B","text":"Visitors damaged the displays."},{"label":"C","text":"New displays are being installed."},{"label":"D","text":"The whole museum is being cleaned."}]'::jsonb,'C','The notice gives installation of new displays as the reason.','core',45,'draft'),
('A2-026','R01','A2','Consumer Economics','Understanding conditions','BOOKSHOP RETURNS
Books may be exchanged within seven days if they are unread and in good condition. Please bring your receipt. Dictionaries and other reference books cannot be exchanged.','Which book can be exchanged?','[{"label":"A","text":"A dictionary bought yesterday."},{"label":"B","text":"A novel that has been read."},{"label":"C","text":"A damaged book without a receipt."},{"label":"D","text":"An unread novel with its receipt."}]'::jsonb,'D','The unread novel meets the condition, and the customer has the receipt.','core',50,'draft'),
('A2-027','R01','A2','Technology and Society','Understanding a message','MESSAGE FROM LEO
Hi Nina, I uploaded the group presentation last night, but I noticed that one picture was missing. I''ve added it now. Please check the latest version before our meeting.','What does Leo want Nina to do?','[{"label":"A","text":"Prepare a different presentation."},{"label":"B","text":"Check the updated presentation."},{"label":"C","text":"Remove all the pictures."},{"label":"D","text":"Change the meeting time."}]'::jsonb,'B','Leo asks Nina to check the latest version after he added the missing picture.','core',40,'draft'),
('A2-028','R01','A2','Education and Learning','Understanding rules','LIBRARY REMINDER
Group discussions are welcome in the glass study room. The main reading area is for quiet work. Please put returned books on the trolley beside the entrance, not back on the shelves.','Where should students talk together?','[{"label":"A","text":"In the glass study room."},{"label":"B","text":"Beside the entrance."},{"label":"C","text":"In the main reading area."},{"label":"D","text":"Between the bookshelves."}]'::jsonb,'A','The glass study room is specifically provided for group discussions.','core',45,'draft'),
('A2-029','R01','A2','Climate and Weather','Understanding a warning','WEATHER UPDATE
Heavy rain is expected this afternoon. The school football practice will move to the covered court. Students should still bring their usual sports clothes.','Where will football practice take place?','[{"label":"A","text":"On the main football field."},{"label":"B","text":"At the town sports centre."},{"label":"C","text":"In the covered court."},{"label":"D","text":"In the school library."}]'::jsonb,'C','The update says practice will move to the covered court.','core',40,'draft'),
('A2-030','R01','A2','Energy and Electricity','Identifying purpose','ENERGY-SAVING REMINDER
Before leaving the computer room, log out of your account and switch off the monitor. The computers should remain on because they are updated automatically overnight.','What should students switch off?','[{"label":"A","text":"The computer monitors."},{"label":"B","text":"The computers."},{"label":"C","text":"The room lights only."},{"label":"D","text":"The automatic update system."}]'::jsonb,'A','The notice asks students to switch off the monitors but leave computers on.','core',45,'draft'),
('B1-016','R01','B1','Media and Youth','Understanding implied meaning','STUDENT NEWSLETTER
Our school newsletter has received more articles this term, but most have come from the same small group of students. The editorial team would like to hear from students who have never submitted work before. Short reports, reviews and photographs are all welcome.','What is the editorial team mainly trying to do?','[{"label":"A","text":"Reduce the number of articles it receives."},{"label":"B","text":"Encourage a wider range of students to contribute."},{"label":"C","text":"Ask regular writers to stop submitting work."},{"label":"D","text":"Replace written articles with photographs."}]'::jsonb,'B','The team wants contributions from students who have not submitted work before.','core',60,'draft'),
('B1-017','R01','B1','Health and Nutrition','Understanding a recommendation','SCHOOL NURSE MESSAGE
Several students have reported feeling tired during morning lessons. There may be different reasons, but skipping breakfast can make it harder to concentrate. Students who regularly feel unwell should speak to a member of staff rather than simply changing what they eat.','What does the nurse suggest about breakfast?','[{"label":"A","text":"It is the only cause of tiredness."},{"label":"B","text":"It should be replaced with a drink."},{"label":"C","text":"Missing it may affect concentration."},{"label":"D","text":"It is unnecessary before morning lessons."}]'::jsonb,'C','The message says skipping breakfast can make concentration more difficult, while recognising other causes.','core',60,'draft'),
('B1-018','R01','B1','Technology and Society','Understanding a warning','ONLINE PRIVACY GUIDE
Deleting a photograph from your profile does not always remove every copy. Other people may have saved or shared it already. Think carefully before posting personal images, especially when they include friends or family members.','What warning does the guide give?','[{"label":"A","text":"Online photographs are always private."},{"label":"B","text":"A deleted photograph may still exist elsewhere."},{"label":"C","text":"Friends cannot share photographs."},{"label":"D","text":"Personal images should never be taken."}]'::jsonb,'B','The guide explains that others may already have saved or shared a deleted image.','core',60,'draft'),
('B1-019','R01','B1','Environment and Pollution','Identifying purpose','RIVER CLEAN-UP DAY
Local residents are invited to help remove rubbish from the riverbank next Saturday. Gloves and collection bags will be provided. Volunteers should wear clothes that can get dirty and meet beside the old bridge. The event will go ahead unless conditions are unsafe.','Who is the event aimed at?','[{"label":"A","text":"Professional cleaning companies only."},{"label":"B","text":"Students who live beside the bridge."},{"label":"C","text":"People from the local community."},{"label":"D","text":"Visitors who want to go boating."}]'::jsonb,'C','The notice explicitly invites local residents to take part.','core',55,'draft'),
('B1-020','R01','B1','Transportation and Energy','Identifying specific information','TRAVEL CARD UPDATE
The Green Travel Card can now be used on all city buses and local trains. It is not valid on express services. Passengers who already own a card do not need to apply for a new one; the change is automatic.','Where can the card be used?','[{"label":"A","text":"On city buses and local trains."},{"label":"B","text":"On every express train."},{"label":"C","text":"Only on buses outside the city."},{"label":"D","text":"On private taxis."}]'::jsonb,'A','The update says it is valid on all city buses and local trains, but not express services.','core',55,'draft'),
('B1-021','R01','B1','College and Career Paths','Understanding suitability','WEEKEND INTERNSHIP
A local design studio is looking for a student intern to help prepare materials for client meetings. Applicants should enjoy working with others and be willing to learn new software. Previous professional experience is not required.','Which applicant is most suitable?','[{"label":"A","text":"Someone who refuses to use computers."},{"label":"B","text":"Someone who enjoys teamwork and learning."},{"label":"C","text":"Someone who can work only during weekdays."},{"label":"D","text":"Someone who already owns a design company."}]'::jsonb,'B','The studio values teamwork and willingness to learn; prior experience is not required.','core',60,'draft'),
('B1-022','R01','B1','Education and Learning','Understanding an opinion','STUDY ADVICE FROM A TEACHER
Students often try to revise everything the night before an examination. This can create unnecessary stress and makes it difficult to remember information. A short review several times a week is usually more useful than one long session at the last minute.','What does the teacher believe?','[{"label":"A","text":"Last-minute study is the best method."},{"label":"B","text":"Students should avoid reviewing their notes."},{"label":"C","text":"Regular revision is generally more effective."},{"label":"D","text":"Examinations should be shorter."}]'::jsonb,'C','The teacher recommends several short reviews rather than one last-minute session.','core',60,'draft'),
('B1-023','R01','B1','Consumer Economics','Understanding conditions','STORE RETURNS POLICY
Most items can be exchanged within 14 days if they are unused and the receipt is available. Items bought in a sale are included in this policy. However, damaged sale items should be reported to staff as soon as possible so that they can be checked.','What does the policy say about sale items?','[{"label":"A","text":"They can never be exchanged."},{"label":"B","text":"They are covered by the usual exchange policy."},{"label":"C","text":"They can be returned without a receipt."},{"label":"D","text":"They must be reported after 14 days."}]'::jsonb,'B','The policy clearly includes sale items in the normal exchange rules, subject to the conditions.','core',60,'draft'),
('B1-024','R01','B1','Sports and Health','Interpreting a message','RUNNING CLUB MESSAGE
Because of the high temperatures expected this week, the club will offer an early morning session as well as its usual afternoon meeting. Members who cannot attend in the morning may still join the afternoon group, but should bring water and take regular breaks.','Why might some members prefer the morning session?','[{"label":"A","text":"The afternoon session has been cancelled."},{"label":"B","text":"The morning session is longer."},{"label":"C","text":"The weather is expected to be cooler earlier."},{"label":"D","text":"Members do not need sports clothes in the morning."}]'::jsonb,'C','The message introduces an early session because of high afternoon temperatures.','core',60,'draft'),
('B1-025','R01','B1','Energy and Electricity','Understanding a report','ENERGY REPORT
The school used more electricity this month than it did last month. The increase happened during a period when several classrooms stayed open later for project work. The report recommends checking room-use patterns before buying new equipment.','What does the report suggest doing first?','[{"label":"A","text":"Replacing all classroom equipment."},{"label":"B","text":"Closing the school during project week."},{"label":"C","text":"Checking how and when rooms are used."},{"label":"D","text":"Increasing the number of evening classes."}]'::jsonb,'C','The report recommends examining room-use patterns before making equipment purchases.','core',60,'draft'),
('B1-026','R01','B1','Cities and Housing','Understanding a complaint','MESSAGE TO THE BUILDING MANAGER
The air conditioner in our shared study room has stopped cooling the room properly. The fan still works, but the temperature remains uncomfortable. Could someone inspect the unit before the examination period begins?','What does the writer want?','[{"label":"A","text":"A new study room to be built."},{"label":"B","text":"The air conditioner to be checked."},{"label":"C","text":"The examination period to be delayed."},{"label":"D","text":"The fan to be removed."}]'::jsonb,'B','The writer asks the manager to arrange an inspection of the air conditioner.','core',55,'draft'),
('B1-027','R01','B1','Climate and Weather','Understanding a possibility','OUTDOOR FAIR UPDATE
The forecast suggests that showers may arrive during Saturday''s fair. Organisers are preparing indoor spaces in case some activities need to move. Visitors should check the event website before travelling for the latest information.','What might happen if it rains?','[{"label":"A","text":"The entire fair will definitely be cancelled."},{"label":"B","text":"All visitors will receive a refund."},{"label":"C","text":"Some activities may take place indoors."},{"label":"D","text":"The event will move to Sunday."}]'::jsonb,'C','The organisers are preparing indoor spaces in case activities need to move.','core',55,'draft'),
('B1-028','R01','B1','Food Production','Understanding a process','FROM FARM TO RESTAURANT
The local food cooperative collects vegetables from nearby farms early each morning. Restaurants receive the produce soon after it is collected, which helps them serve fresher meals. The cooperative also shares information about where each product was grown.','What is one benefit of the cooperative?','[{"label":"A","text":"Restaurants receive produce soon after harvest."},{"label":"B","text":"Farmers no longer need to grow vegetables."},{"label":"C","text":"Restaurants can avoid telling customers where food comes from."},{"label":"D","text":"All vegetables are stored for several weeks."}]'::jsonb,'A','The text says the system helps restaurants receive fresher produce soon after collection.','core',60,'draft'),
('B1-029','R01','B1','Artificial Intelligence','Understanding advice','STUDENT GUIDE TO AI TOOLS
AI tools can help explain unfamiliar ideas and suggest ways to improve a piece of writing. However, they sometimes produce incorrect information or misunderstand a question. Students should compare important claims with reliable sources before using them.','What should students do with important information from AI tools?','[{"label":"A","text":"Accept it without checking."},{"label":"B","text":"Delete every suggestion."},{"label":"C","text":"Check it against reliable sources."},{"label":"D","text":"Use it only for spelling."}]'::jsonb,'C','The guide advises students to verify important claims using reliable sources.','core',60,'draft'),
('B1-030','R01','B1','Space Exploration','Understanding relevance','SPACE EXHIBITION REVIEW
The exhibition includes models of satellites and explanations of how they support communication, weather forecasting and navigation. Visitors may expect to see distant planets, but the most interesting section shows how space technology is used in everyday life.','What does the reviewer find especially interesting?','[{"label":"A","text":"The size of the exhibition building."},{"label":"B","text":"The way space technology affects daily life."},{"label":"C","text":"The number of planets shown in the models."},{"label":"D","text":"The history of the museum''s visitors."}]'::jsonb,'B','The reviewer highlights practical uses of space technology in everyday life.','core',60,'draft'),
('B2-016','R01','B2','Media and Youth','Understanding policy','STUDENT MEDIA POLICY
The editorial board welcomes opinion pieces on current issues. Submissions should present a clear argument and acknowledge relevant opposing views. Articles that make unsupported claims may be returned for revision before publication; this is intended to strengthen the discussion rather than discourage contributors.','What is the main purpose of returning some articles?','[{"label":"A","text":"To prevent students from discussing controversial issues."},{"label":"B","text":"To improve the quality and balance of arguments."},{"label":"C","text":"To ensure that every article expresses the same opinion."},{"label":"D","text":"To reduce the number of contributors."}]'::jsonb,'B','The policy says revision is intended to strengthen discussion and encourage supported, balanced arguments.','core',75,'draft'),
('B2-017','R01','B2','Health and Nutrition','Interpreting a qualification','COMMUNITY WELLNESS PROGRAMME
The programme combines guided exercise with workshops on food choices and sleep habits. Participants often report feeling more energetic, although individual experiences vary. The organisers stress that the programme is designed to support healthier routines, not to promise a particular change in body weight.','What limitation do the organisers emphasise?','[{"label":"A","text":"The programme is only suitable for athletes."},{"label":"B","text":"The workshops do not discuss food."},{"label":"C","text":"Participants are guaranteed the same results."},{"label":"D","text":"The programme does not guarantee weight loss."}]'::jsonb,'D','The organisers explicitly state that they do not promise a particular change in body weight.','core',70,'draft'),
('B2-018','R01','B2','Technology and Society','Understanding stance','REVIEW OF A LEARNING PLATFORM
The platform offers useful tools for organising assignments and receiving feedback. Its interface is generally clear, although the notification system can become distracting during focused work. With more control over alerts, it could become a valuable addition to independent study.','How does the reviewer feel about the platform?','[{"label":"A","text":"Entirely negative about its educational value."},{"label":"B","text":"Positive, but aware of an area that needs improvement."},{"label":"C","text":"Uncertain whether students should use technology."},{"label":"D","text":"Completely satisfied with every feature."}]'::jsonb,'B','The reviewer recognises clear benefits while identifying the notification system as a weakness.','core',75,'draft'),
('B2-019','R01','B2','Environment and Pollution','Understanding rationale','RECYCLING POLICY UPDATE
The city will introduce separate collection for household food waste over the coming year. Residents will receive containers and guidance before the new system becomes compulsory. The transition period is intended to give households time to understand the requirements and adjust their routines.','Why is there a transition period?','[{"label":"A","text":"To allow residents time to adapt to the new system."},{"label":"B","text":"To make food-waste collection optional forever."},{"label":"C","text":"To delay the delivery of all household rubbish."},{"label":"D","text":"To encourage residents to stop recycling."}]'::jsonb,'A','The text directly explains that the period gives households time to understand and adjust.','core',70,'draft'),
('B2-020','R01','B2','Transportation and Energy','Understanding purpose','BUS NETWORK CONSULTATION
The transport authority has published a proposed redesign of the city bus network. Residents are invited to comment on route changes before the final plan is approved. The authority says feedback will be considered alongside passenger data and operating requirements.','What is the purpose of the consultation?','[{"label":"A","text":"To announce that all routes have already changed."},{"label":"B","text":"To ask residents to approve higher fares."},{"label":"C","text":"To gather views before the network plan is finalised."},{"label":"D","text":"To replace passenger data with public opinion."}]'::jsonb,'C','The authority is collecting comments before approving the final plan.','core',70,'draft'),
('B2-021','R01','B2','College and Career Paths','Understanding implication','CAREER DEVELOPMENT PROGRAMME
The programme pairs students with professionals from different industries. Rather than focusing only on job-specific knowledge, participants are encouraged to reflect on how they communicate, solve problems and respond to unfamiliar situations. Organisers believe these habits are transferable across many careers.','What is the programme''s broader aim?','[{"label":"A","text":"To prepare students for one particular job."},{"label":"B","text":"To develop skills that are useful in different careers."},{"label":"C","text":"To replace academic study with workplace experience."},{"label":"D","text":"To assess students only on technical knowledge."}]'::jsonb,'B','The programme focuses on transferable skills that can be used across careers.','core',75,'draft'),
('B2-022','R01','B2','Education and Learning','Understanding an argument','ACTIVE STUDY WORKSHOPS
The workshops ask students to explain ideas, compare examples and apply concepts to unfamiliar situations. This approach can feel slower than simply reviewing notes, but organisers argue that active use of information helps students recognise what they understand and where further work is needed.','What is the organisers'' main argument?','[{"label":"A","text":"Applying knowledge can reveal understanding more effectively than passive review."},{"label":"B","text":"Students should stop taking notes altogether."},{"label":"C","text":"The workshops are designed to make learning feel faster."},{"label":"D","text":"Unfamiliar examples should be avoided during revision."}]'::jsonb,'A','The organisers argue that active application helps students identify both understanding and gaps.','core',75,'draft'),
('B2-023','R01','B2','Consumer Economics','Interpreting advice','BANK ACCOUNT NOTICE
The bank will introduce a monthly service fee for accounts that do not meet the new activity conditions. Customers who rarely use their accounts may wish to review the alternatives available before the change takes effect. The bank will publish a full list of options online.','What is the notice suggesting to some customers?','[{"label":"A","text":"They should close every account immediately."},{"label":"B","text":"They should ignore the upcoming change."},{"label":"C","text":"They should consider whether another account would suit them better."},{"label":"D","text":"They should use the account more often without checking the conditions."}]'::jsonb,'C','The notice advises infrequent users to review available alternatives before the change.','core',75,'draft'),
('B2-024','R01','B2','Sports and Health','Understanding emphasis','ATHLETE RECOVERY ARTICLE
Training plans often focus on the intensity and frequency of exercise, yet performance also depends on what happens between sessions. Adequate rest allows the body to adapt to training. Ignoring recovery may undermine the benefits of even a carefully designed programme.','What does the article emphasise?','[{"label":"A","text":"Rest is an essential part of effective training."},{"label":"B","text":"Training intensity is the only factor affecting performance."},{"label":"C","text":"Recovery matters only after competitions."},{"label":"D","text":"A carefully designed plan removes the need for rest."}]'::jsonb,'A','The article stresses that recovery is necessary for the body to adapt and benefit from training.','core',70,'draft'),
('B2-025','R01','B2','Energy and Electricity','Understanding a conclusion','ENERGY EFFICIENCY REPORT
The installation of efficient lighting reduced electricity use in several school buildings. However, the savings differed considerably between sites. The report notes that some buildings continued to leave lights on in empty rooms, suggesting that equipment improvements alone cannot determine the final result.','What conclusion does the report support?','[{"label":"A","text":"Efficient lighting has no effect on electricity use."},{"label":"B","text":"Staff behaviour can influence the savings achieved."},{"label":"C","text":"All school buildings use electricity in the same way."},{"label":"D","text":"Lighting should be removed from empty rooms permanently."}]'::jsonb,'B','The report links differences in savings to how occupants use the buildings.','core',75,'draft'),
('B2-026','R01','B2','Cities and Housing','Understanding a condition','BALCONY GARDEN GUIDELINES
Residents may grow plants on their balconies provided that containers are secure and drainage does not affect neighbouring properties. Building staff must also be able to reach external maintenance points. Residents should therefore avoid placing large items against access panels.','What must residents take care to do?','[{"label":"A","text":"Keep access panels clear for maintenance."},{"label":"B","text":"Remove every plant before the inspection."},{"label":"C","text":"Allow water to drain onto neighbouring balconies."},{"label":"D","text":"Place heavy containers near the balcony edge."}]'::jsonb,'A','The guidelines require maintenance access to remain available.','core',70,'draft'),
('B2-027','R01','B2','Climate and Weather','Understanding limitation','LOCAL WEATHER DATA
Regional climate averages are useful for identifying broad patterns, but they cannot describe conditions in every neighbourhood. Buildings, hills and nearby water can all influence local temperatures and rainfall. Residents should therefore treat general forecasts as guidance rather than a precise account of every street.','What limitation of regional averages is highlighted?','[{"label":"A","text":"They are never based on reliable observations."},{"label":"B","text":"They cannot show broad climate patterns."},{"label":"C","text":"They may not represent conditions in every local area."},{"label":"D","text":"They are useful only near large bodies of water."}]'::jsonb,'C','The text explains that local features can make conditions differ from regional averages.','core',75,'draft'),
('B2-028','R01','B2','Food Production','Understanding consequence','LOCAL FOOD SUPPLY
Restaurants that buy directly from small farms can develop closer relationships with producers and learn more about growing methods. However, the range of available ingredients may change with the season and weather. Chefs who choose this approach need to be flexible when planning menus.','What challenge may restaurants face?','[{"label":"A","text":"A less predictable range of ingredients."},{"label":"B","text":"A complete lack of information about producers."},{"label":"C","text":"The need to stop changing their menus."},{"label":"D","text":"A requirement to buy only imported food."}]'::jsonb,'A','Seasonal and weather conditions can affect which ingredients are available.','core',70,'draft'),
('B2-029','R01','B2','Artificial Intelligence','Understanding a qualification','GUIDANCE ON AI-ASSISTED WORK
AI systems can generate suggestions quickly, but their confident tone should not be mistaken for proof of accuracy. Users remain responsible for checking evidence, considering context and deciding whether a recommendation is appropriate. The technology is best treated as support for judgement, not a substitute for it.','What is the writer''s central message?','[{"label":"A","text":"AI recommendations should always be followed."},{"label":"B","text":"AI tools are useful only for generating creative ideas."},{"label":"C","text":"Human judgement remains necessary when using AI."},{"label":"D","text":"AI systems are unable to produce useful suggestions."}]'::jsonb,'C','The text presents AI as a support tool while emphasising users'' responsibility for decisions.','core',75,'draft'),
('B2-030','R01','B2','Space Exploration','Understanding balance','PUBLIC SPACE FUNDING
Supporters of space research point to scientific discoveries and technologies that may benefit society in the long term. Critics argue that public money should first address urgent needs on Earth. A recent policy paper suggests that the debate should focus less on choosing one priority and more on explaining how different investments serve public interests.','What approach does the policy paper favour?','[{"label":"A","text":"Ending all space research until every problem on Earth is solved."},{"label":"B","text":"Balancing different investments and explaining their public value."},{"label":"C","text":"Funding space research without considering its costs."},{"label":"D","text":"Treating scientific discoveries as the only public priority."}]'::jsonb,'B','The paper proposes considering how different investments serve public interests rather than choosing only one.','core',75,'draft')
on conflict (question_code) do update set
 category=excluded.category, cefr_level=excluded.cefr_level, topic=excluded.topic,
 skill=excluded.skill, passage=excluded.passage, prompt=excluded.prompt,
 options=excluded.options, correct_option=excluded.correct_option,
 rationale=excluded.rationale, difficulty=excluded.difficulty,
 estimated_seconds=excluded.estimated_seconds, status=excluded.status, updated_at=now();
commit;
select cefr_level, count(*) as batch_questions
from public.reading_question_bank
where question_code between 'A2-016' and 'B2-030'
group by cefr_level order by cefr_level;
